export const SIZE=30;
export const GOODS={passengers:{name:'승객',icon:'◉',rate:9,color:'#5b8fdf'},wood:{name:'목재',icon:'▥',rate:7,color:'#96784e'},ore:{name:'철광석',icon:'◆',rate:9,color:'#8f8f9a'},steel:{name:'강철',icon:'▰',rate:14,color:'#7899a8'},grain:{name:'곡물',icon:'♧',rate:7,color:'#c1a255'},food:{name:'식품',icon:'◈',rate:13,color:'#db946c'},goods:{name:'생활용품',icon:'▣',rate:16,color:'#b28cbd'}};
export const MODES={train:{name:'철도',vehicle:'기관차',icon:'▥',color:'#cf765b',cost:2900,facility:1000,tile:150,cap:28,speed:2.8,upkeep:90,category:'rail',unlock:0},bus:{name:'버스',vehicle:'버스',icon:'▤',color:'#e9ba54',cost:800,facility:300,tile:60,cap:14,speed:2.1,upkeep:35,category:'road',unlock:0},truck:{name:'트럭',vehicle:'화물차',icon:'▰',color:'#65a58e',cost:1100,facility:350,tile:60,cap:18,speed:1.8,upkeep:45,category:'road',unlock:0},ship:{name:'해운',vehicle:'화물선',icon:'⚓',color:'#5993bb',cost:4400,facility:1500,tile:12,cap:65,speed:1.3,upkeep:130,category:'port',unlock:60},plane:{name:'항공',vehicle:'여객기',icon:'✈',color:'#a08dbe',cost:8500,facility:2800,tile:0,cap:38,speed:6.2,upkeep:220,category:'air',unlock:220}};
export const PLACES=[
 ['청해시','city',8,19,true,720],['솔빛마을','city',8,11,false,420],['중앙시','city',15,14,false,1100],['해오름','city',23,9,true,640],['은빛항','city',22,20,true,560],['바람섬','city',4,4,true,300],
 ['푸른숲','forest',11,6,false,0],['솔빛 제재소','sawmill',12,10,false,0],['철산광산','mine',19,5,false,0],['동부 제철소','steelworks',20,12,false,0],['해안 제조소','factory',24,17,true,0],['들녘농장','farm',10,17,false,0],['청해 식품공장','foodplant',16,19,false,0],['동백섬','city',26,3,true,380]
].map(([name,type,x,y,coast,pop],id)=>({id,name,type,x,y,coast,pop}));
export const TYPES={city:{name:'도시',out:'passengers',accept:['passengers','food','goods']},forest:{name:'벌목장',out:'wood',accept:[]},sawmill:{name:'제재소',out:'goods',accept:['wood'],recipe:{wood:2},yield:3},mine:{name:'광산',out:'ore',accept:[]},steelworks:{name:'제철소',out:'steel',accept:['ore'],recipe:{ore:2},yield:3},factory:{name:'제조소',out:'goods',accept:['steel'],recipe:{steel:2},yield:4},farm:{name:'농장',out:'grain',accept:[]},foodplant:{name:'식품공장',out:'food',accept:['grain'],recipe:{grain:2},yield:3}};
export const EVENTS=[{name:'평온한 바다',desc:'운송 시장이 안정적입니다.',factor:1,ship:1,plane:1},{name:'관광 성수기',desc:'승객 운임이 35% 상승합니다.',factor:1.35,ship:1,plane:1,passenger:true},{name:'해상 강풍',desc:'선박 속도 25%, 항공 속도 15% 감소.',factor:1,ship:.75,plane:.85},{name:'산업 호황',desc:'화물 운임이 30% 상승합니다.',factor:1.3,ship:1,plane:1,freight:true},{name:'지역 축제',desc:'승객 운임이 20% 상승합니다.',factor:1.2,ship:1,plane:1,passenger:true}];
export function land(x,y){return (x-15)**2/112+(y-14)**2/104<1|| (x-17)**2/55+(y-7)**2/28<1||(x-4)**2+(y-4)**2<7||(x-26)**2+(y-3)**2<7||(x-4)**2+(y-21)**2<5;}
const key=(x,y)=>x+','+y;const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const ocean=new Set(),coastQueue=[];
for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++)if((x===0||y===0||x===SIZE-1||y===SIZE-1)&&!land(x,y)){ocean.add(key(x,y));coastQueue.push({x,y})}
for(let i=0;i<coastQueue.length;i++){const p=coastQueue[i];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy,k=key(x,y);if(x>=0&&y>=0&&x<SIZE&&y<SIZE&&!land(x,y)&&!ocean.has(k)){ocean.add(k);coastQueue.push({x,y})}}}
const dockCache=new Map();
export function dock(n){const k=key(n.x,n.y);if(dockCache.has(k))return dockCache.get(k);let best=null,d=Infinity;for(const p of coastQueue){const v=dist(n,p);if(v<d){d=v;best={...p}}}dockCache.set(k,best);return best;}
export function pathFor(a,b,mode){if(mode==='plane')return [{x:a.x,y:a.y},{x:b.x,y:b.y}];const sea=mode==='ship',start=sea?dock(a):a,end=sea?dock(b):b;
 const open=[{x:start.x,y:start.y,g:0,f:0}],cost=new Map([[key(start.x,start.y),0]]),prev=new Map(),closed=new Set();let found=false;
 while(open.length){open.sort((a,b)=>a.f-b.f);const p=open.shift(),pk=key(p.x,p.y);if(closed.has(pk))continue;if(p.x===end.x&&p.y===end.y){found=true;break}closed.add(pk);for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy;if(x<0||y<0||x>=SIZE||y>=SIZE||sea&&land(x,y))continue;const nk=key(x,y),g=p.g+(sea?1:land(x,y)?1:7);if(g<(cost.get(nk)??Infinity)){cost.set(nk,g);prev.set(nk,pk);open.push({x,y,g,f:g+Math.abs(x-end.x)+Math.abs(y-end.y)})}}}
 if(!found)return null;const points=[];let cur=key(end.x,end.y);while(cur){const [x,y]=cur.split(',').map(Number);points.unshift({x,y});cur=prev.get(cur)}return points;}
export function length(path){return path.slice(1).reduce((sum,p,i)=>sum+dist(p,path[i]),0)}
export function atPath(path,progress){
 let distance=length(path)*Math.max(0,Math.min(1,progress));
 for(let i=1;i<path.length;i++){
  const d=dist(path[i-1],path[i]);
  if(distance<=d){const t=d?distance/d:0;return {x:path[i-1].x+(path[i].x-path[i-1].x)*t,y:path[i-1].y+(path[i].y-path[i-1].y)*t,angle:Math.atan2(path[i].y-path[i-1].y,path[i].x-path[i-1].x)}}
  distance-=d;
 }
 return {...path.at(-1),angle:0};
}
export class Company{
 constructor(){this.visuals=[];this.version=1;this.cash=28000;this.loan=0;this.day=0;this.delivered=0;this.revenue=0;this.expenses=0;this.monthIncome=0;this.monthCost=0;this.history=[];this.routes=[];this.nodes=PLACES.map(n=>({...n,stock:{[TYPES[n.type].out]:n.type==='city'?45:TYPES[n.type].recipe?0:60},facilities:{},served:0}));this.nextId=1;this.completed=[];this.milestones=[];this.won=false;this.notices=[];this.activeContract=null;this.contractSerial=0;this.contracts=[];this.makeContracts();this.autosaveDue=false;}
 notify(text){this.notices.push(text);this.notices=this.notices.slice(-8)}
 event(){return EVENTS[Math.floor(this.day/75)%EVENTS.length]}
 unlock(mode){return this.delivered>=MODES[mode].unlock}
 validCargo(a,b,cargo,mode){return a.id!==b.id&&TYPES[a.type].out===cargo&&TYPES[b.type].accept.includes(cargo)&&(mode!=='bus'||cargo==='passengers')&&(mode!=='truck'||cargo!=='passengers')&&(mode!=='plane'||cargo==='passengers')&&(mode!=='ship'||a.coast&&b.coast)}
 quote(aId,bId,mode,cargo){const a=this.nodes[aId],b=this.nodes[bId],m=MODES[mode];if(!a||!b||!m)return {error:'출발지와 도착지를 선택하세요.'};if(!this.unlock(mode))return {error:`누적 ${m.unlock}명·톤 운송 후 해제됩니다.`};if(!this.validCargo(a,b,cargo,mode))return {error:'이 운송수단으로 연결할 수 없는 화물 또는 목적지입니다.'};if(this.routes.some(r=>r.mode===mode&&r.cargo===cargo&&(r.a===aId&&r.b===bId||cargo==='passengers'&&r.a===bId&&r.b===aId)))return {error:'이미 같은 노선이 있습니다. 기존 노선에 차량을 추가하세요.'};const path=pathFor(a,b,mode);if(!path)return {error:'연결 가능한 경로를 찾지 못했습니다.'};const bridge=mode!=='ship'&&mode!=='plane'?path.filter(p=>!land(p.x,p.y)).length:0;const facility=[a,b].filter(n=>!n.facilities[m.category]).length*m.facility;const infra=Math.round(length(path)*m.tile+bridge*550+facility);return {path,bridge,infra,vehicle:m.cost,total:infra+m.cost,distance:length(path),mode,cargo,a:aId,b:bId};}
 build(a,b,mode,cargo){const q=this.quote(a,b,mode,cargo);if(q.error)return q;if(this.cash<q.total)return {error:'자금이 부족합니다. 짧은 노선부터 시작하거나 은행 대출을 이용하세요.'};const m=MODES[mode];this.cash-=q.total;this.expenses+=q.total;for(const id of [a,b])this.nodes[id].facilities[m.category]??=1;const route={id:this.nextId++,a,b,mode,cargo,path:q.path,distance:q.distance,infra:q.infra,revenue:0,cost:0,deliveries:0,enabled:true,vehicles:[this.vehicle(mode)],created:this.day};this.routes.push(route);this.notify(`${this.nodes[a].name} ↔ ${this.nodes[b].name} 개통`);this.checkGoals();return route;}
 vehicle(mode){return {id:this.nextId++,progress:0,dir:1,wait:1,load:0,loadedAt:null,condition:100,level:1,age:0,tripCount:0}}
 addVehicle(id){const r=this.routes.find(r=>r.id===id);if(!r||r.vehicles.length>=6)return false;const cost=MODES[r.mode].cost;if(this.cash<cost)return false;this.cash-=cost;this.expenses+=cost;const v=this.vehicle(r.mode);v.wait=1+r.vehicles.length*2;r.vehicles.push(v);return true;}
 upgradeVehicle(id,vid){const r=this.routes.find(r=>r.id===id),v=r?.vehicles.find(v=>v.id===vid);if(!v||v.level>=3)return false;const cost=Math.round(MODES[r.mode].cost*.65*v.level);if(this.cash<cost)return false;this.cash-=cost;this.expenses+=cost;v.level++;v.condition=100;return true}
 replaceVehicle(id,vid){const r=this.routes.find(r=>r.id===id),v=r?.vehicles.find(v=>v.id===vid);if(!v)return false;const cost=Math.round(MODES[r.mode].cost*.55);if(this.cash<cost)return false;this.cash-=cost;this.expenses+=cost;v.condition=100;v.age=0;return true}
 sellVehicle(id,vid){const r=this.routes.find(r=>r.id===id),v=r?.vehicles.find(v=>v.id===vid);if(!v||r.vehicles.length<=1)return false;this.returnLoad(r,v);this.cash+=Math.floor(MODES[r.mode].cost*.55*v.condition/100);r.vehicles=r.vehicles.filter(x=>x.id!==vid);return true}
 returnLoad(r,v){if(v.load&&this.nodes[v.loadedAt]){const n=this.nodes[v.loadedAt];n.stock[r.cargo]=(n.stock[r.cargo]||0)+v.load;v.load=0}}
 removeRoute(id){const r=this.routes.find(r=>r.id===id);if(!r)return false;for(const v of r.vehicles)this.returnLoad(r,v);this.cash+=Math.round(r.infra*.65+r.vehicles.reduce((s,v)=>s+MODES[r.mode].cost*.55*v.condition/100,0));this.routes=this.routes.filter(x=>x.id!==id);return true}
 upgradeFacility(nodeId,category){const n=this.nodes[nodeId],level=n?.facilities[category];if(!level||level>=3)return false;const cost=800*level;if(this.cash<cost)return false;this.cash-=cost;this.expenses+=cost;n.facilities[category]++;return true;}
 borrow(){if(this.loan>=30000)return false;this.loan+=10000;this.cash+=10000;this.notify('운영 자금 10,000 대출 · 월 이자 2%');return true}
 repay(){if(this.loan<=0||this.cash<Math.min(this.loan,10000))return false;const amount=Math.min(this.loan,10000);this.loan-=amount;this.cash-=amount;return true}
 makeContracts(){const choices=[[6,7,'wood',40],[11,12,'grain',50],[8,9,'ore',45],[7,2,'goods',35],[12,0,'food',40],[9,10,'steel',40],[0,1,'passengers',70],[3,4,'passengers',70]];const base=Math.floor(this.day/60);this.contracts=Array.from({length:3},(_,i)=>{const [a,b,cargo,amount]=choices[(base+i*2)%choices.length];return {id:++this.contractSerial,a,b,cargo,amount,done:0,reward:1500+amount*10,deadline:this.day+100}})}
 acceptContract(id){if(this.activeContract)return false;const c=this.contracts.find(x=>x.id===id);if(!c||c.deadline<=this.day)return false;this.activeContract={...c};return true}
 worth(){return Math.round(this.cash-this.loan+this.routes.reduce((s,r)=>s+r.infra*.65+r.vehicles.reduce((n,v)=>n+MODES[r.mode].cost*.65*v.condition/100,0),0))}
 goalData(){const cities=new Set(this.routes.flatMap(r=>[r.a,r.b]).filter(id=>this.nodes[id].type==='city'));return [{name:'첫 번째 연결',desc:'첫 운송 노선을 개통하세요.',value:this.routes.length,target:1,reward:1500},{name:'움직이는 경제',desc:'승객·화물 120명·톤 운송',value:this.delivered,target:120,reward:2500},{name:'산업의 연결',desc:'식품 또는 생활용품 100톤 납품',value:this.completed.filter(c=>['food','goods'].includes(c.cargo)).reduce((s,c)=>s+c.amount,0),target:100,reward:4000},{name:'섬을 잇는 기업',desc:'도시 6곳 연결 + 5종 운송수단 운행',value:Math.min(6,cities.size)+new Set(this.routes.filter(r=>r.enabled).map(r=>r.mode)).size,target:11,reward:6000},{name:'블루포트의 시대',desc:'누적 운송 2,500 · 기업 가치 100,000',value:Math.min(2500,this.delivered)/2500+Math.min(100000,Math.max(0,this.worth()))/100000,target:2,reward:10000}];}
 checkGoals(){const goals=this.goalData();for(let i=0;i<goals.length;i++){if(i>0&&!this.milestones.includes(i-1))break;if(!this.milestones.includes(i)&&goals[i].value>=goals[i].target){this.milestones.push(i);this.cash+=goals[i].reward;this.notify(`목표 달성: ${goals[i].name} · 보상 ${goals[i].reward.toLocaleString()}`)}}if(this.milestones.length===5&&!this.won){this.won=true;this.notify('블루포트 교통망 완성! 자유 경영을 계속할 수 있습니다.')}}
 deliver(r,v,dest){if(!v.load)return;const n=this.nodes[dest],amount=v.load,ev=this.event();const factor=(r.cargo==='passengers'&&ev.passenger||r.cargo!=='passengers'&&ev.freight)?ev.factor:1;const distance=dist(this.nodes[r.a],this.nodes[r.b]);const income=Math.round(amount*GOODS[r.cargo].rate*(1+distance*.16)*factor);this.visuals.push({node:dest,income});this.visuals=this.visuals.slice(-20);this.cash+=income;this.revenue+=income;this.monthIncome+=income;r.revenue+=income;r.deliveries+=amount;this.delivered+=amount;n.served+=amount;if(n.type==='city'){n.pop+=amount*(r.cargo==='passengers'?.35:1.2)}else n.stock[r.cargo]=Math.min(800,(n.stock[r.cargo]||0)+amount);this.completed.push({cargo:r.cargo,amount,day:this.day});if(this.completed.length>1000){const totals={};for(const c of this.completed)totals[c.cargo]=(totals[c.cargo]||0)+c.amount;this.completed=Object.entries(totals).map(([cargo,amount])=>({cargo,amount,day:this.day}))}const contract=this.activeContract;if(contract&&contract.a===v.loadedAt&&contract.b===dest&&contract.cargo===r.cargo){contract.done+=amount;if(contract.done>=contract.amount){this.cash+=contract.reward;this.notify(`운송 계약 완료 · 보상 ${contract.reward.toLocaleString()}`);this.activeContract=null;this.makeContracts()}}v.load=0;v.loadedAt=null;v.tripCount++;}
 step(dt){dt=Math.min(1,Math.max(0,dt));if(!dt)return;const oldMonth=Math.floor(this.day/30),oldEvent=Math.floor(this.day/75),oldOffer=Math.floor(this.day/60);this.day+=dt;
 for(const n of this.nodes){const type=TYPES[n.type],out=type.out;n.stock[out]??=0;if(n.type==='city')n.stock[out]=Math.min(n.pop*.7,n.stock[out]+dt*(2+n.pop*.004));else if(!type.recipe)n.stock[out]=Math.min(500,n.stock[out]+dt*6);else{const input=Object.keys(type.recipe)[0],need=type.recipe[input],batches=Math.min((n.stock[input]||0)/need,dt*3,(800-n.stock[out])/type.yield);if(batches>0){n.stock[input]-=batches*need;n.stock[out]+=batches*type.yield}}}
 for(const r of this.routes){if(!r.enabled)continue;const m=MODES[r.mode],ev=this.event();for(const v of r.vehicles){v.age+=dt;v.condition=Math.max(25,100-v.age/15);if(v.wait>0){v.wait-=dt;if(v.wait<=0){const at=v.dir===1?r.a:r.b,n=this.nodes[at],available=TYPES[n.type].out===r.cargo?(n.stock[r.cargo]||0):0;v.load=Math.min(Math.floor(available),Math.floor(m.cap*(1+.35*(v.level-1))));if(v.load>0){n.stock[r.cargo]-=v.load;v.loadedAt=at}}continue}const traffic=this.routes.filter(o=>o.enabled&&o.mode===r.mode&&(o.a===r.a||o.b===r.b)).length;const capacity=(this.nodes[r.a].facilities[m.category]||1)+(this.nodes[r.b].facilities[m.category]||1);const congestion=1/(1+Math.max(0,traffic+r.vehicles.length-2-capacity)*.15);const weather=r.mode==='ship'?ev.ship:r.mode==='plane'?ev.plane:1;v.progress+=v.dir*dt*m.speed*(1+.22*(v.level-1))*(.55+v.condition*.0045)*weather*congestion/Math.max(1,r.distance);if(v.progress>=1||v.progress<=0){const dest=v.dir===1?r.b:r.a;v.progress=v.dir===1?1:0;this.deliver(r,v,dest);v.dir*=-1;v.wait=Math.max(.5,2/(this.nodes[dest].facilities[m.category]||1));}}}
 if(Math.floor(this.day/30)>oldMonth){let cost=this.loan*.02;for(const r of this.routes){const upkeep=MODES[r.mode].upkeep*r.vehicles.length*(r.enabled?1:.3)+r.distance*2;r.cost+=upkeep;cost+=upkeep}this.cash-=cost;this.expenses+=cost;this.monthCost+=cost;this.history.push({month:oldMonth+1,income:this.monthIncome,cost:this.monthCost,cash:this.cash});this.history=this.history.slice(-12);this.monthIncome=0;this.monthCost=0;this.autosaveDue=true;}
 if(Math.floor(this.day/75)>oldEvent)this.notify(`${this.event().name} — ${this.event().desc}`);if(Math.floor(this.day/60)>oldOffer&&!this.activeContract)this.makeContracts();if(this.activeContract&&this.day>this.activeContract.deadline){this.notify('운송 계약 기한이 지났습니다. 위약금 없이 다음 계약에 도전하세요.');this.activeContract=null;this.makeContracts()}this.checkGoals();}
 toJSON(){return {...this,notices:[],visuals:[],autosaveDue:false}}
 static restore(data){if(!data||data.version!==1||!Array.isArray(data.nodes)||data.nodes.length!==PLACES.length||!Array.isArray(data.routes)||data.routes.length>100||!Number.isFinite(data.cash)||!Number.isFinite(data.day)||data.day<0||!Number.isFinite(data.delivered)||data.delivered<0)throw Error('저장 파일 형식을 확인해주세요.');for(let i=0;i<data.nodes.length;i++){const n=data.nodes[i];if(n.id!==i||!n.stock||!n.facilities||!Number.isFinite(n.pop)||n.pop<0||Object.values(n.stock).some(v=>!Number.isFinite(v)||v<0)||Object.entries(n.facilities).some(([k,v])=>!['rail','road','port','air'].includes(k)||!Number.isInteger(v)||v<1||v>3))throw Error('시설 데이터 오류');Object.assign(n,PLACES[i],{pop:n.pop});}
 for(const r of data.routes){if(!MODES[r.mode]||!GOODS[r.cargo]||!data.nodes[r.a]||!data.nodes[r.b]||!Array.isArray(r.vehicles)||r.vehicles.length<1||r.vehicles.length>6||!Number.isFinite(r.distance)||r.distance<=0||!Array.isArray(r.path)||r.path.length<2||r.path.length>1000||r.path.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>=SIZE||p.y<0||p.y>=SIZE))throw Error('노선 데이터 오류');for(const v of r.vehicles)if(!Number.isFinite(v.progress)||v.progress<0||v.progress>1||![1,-1].includes(v.dir)||!Number.isFinite(v.load)||v.load<0||!Number.isFinite(v.condition)||!Number.isInteger(v.level)||v.level<1||v.level>3)throw Error('차량 데이터 오류')}
 if(!Array.isArray(data.completed)||!Array.isArray(data.milestones)||!Array.isArray(data.history)||!Array.isArray(data.contracts)||!Number.isFinite(data.loan)||!Number.isFinite(data.nextId))throw Error('경영 데이터 오류');const c=Object.assign(new Company(),data);c.notices=[];c.visuals=[];c.autosaveDue=false;return c;}
}
